import React from "react";

export default function Table({ data }) {
  return (
    <div>
      <table
        border
        width="100%"
        className="mb-10 my-5 border border-zinc-200 rounded shadow-md p-2 border-b-2"
      >
        <thead>
          <tr className="bg-gray-100 p-1 ">
            <td className="font-bold border border-gray-400">No.</td>
            <td className="font-bold border border-gray-400">Reference No.</td>
            <td className="font-bold border border-gray-400">Name</td>
            <td className="font-bold border border-gray-400">Phone</td>
            <td className="font-bold border border-gray-400">Amount</td>
            <td className="font-bold border border-gray-400">Issued By</td>
            <td className="font-bold border border-gray-400">Route</td>
            <td className="font-bold border border-gray-400">Items</td>
            <td className="font-bold border border-gray-400">Date Created</td>
          </tr>
        </thead>
        {data.map((ticket, index) => (
          <React.Fragment key={ticket.id}>
            <tbody className="border border-gray-300 text-smALL">
              <tr className="h-10">
                <td className="border border-gray-300">{index + 1}</td>
                <td className="border border-gray-300">
                  {ticket.reference_number}
                </td>
                <td className="border border-gray-300">
                  {ticket.first_name && ticket.last_name
                    ? ticket.first_name + " " + ticket.last_name
                    : "N/A"}
                </td>
                <td className="border border-gray-300">
                  {ticket.passenger_phone ? ticket.passenger_phone : "N/A"}
                </td>
                <td className="border border-gray-300">
                  {parseFloat(ticket.ticket_total_amount).toFixed(2)}
                </td>
                <td className="border border-gray-300">{ticket.owner_title}</td>
                <td className="border border-gray-300">{ticket.route_title}</td>
                {ticket.items && ticket.items.length ? (
                  <td className="border border-gray-300">
                    {ticket.items.map((item) => {
                      return (
                        <p>
                          {item.quantity} x {item.title}@KES
                          {parseFloat(item.price)} = KES
                          {parseFloat(item.item_total_amount)}
                        </p>
                      );
                    })}
                  </td>
                ) : (
                  <td className="border border-gray-300">N/A</td>
                )}
                <td>{ticket.created}</td>
              </tr>
            </tbody>
          </React.Fragment>
        ))}
      </table>
    </div>
  );
}
